def transform(grid):
    h, w = len(grid), len(grid[0])

    # Locate the full separator rows and columns.
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != 0]
    sep_cols = [c for c in range(w) if all(grid[r][c] == grid[0][c] for r in range(h)) and grid[0][c] != 0]

    row_starts = [0] + [r + 1 for r in sep_rows]
    col_starts = [0] + [c + 1 for c in sep_cols]
    row_ends = sep_rows + [h]
    col_ends = sep_cols + [w]

    # Find the template in a tile other than the first column.
    pattern = None
    for ri, (rs, re) in enumerate(zip(row_starts, row_ends)):
        for ci, (cs, ce) in enumerate(zip(col_starts, col_ends)):
            if ci == 0:
                continue
            pts = [(r - rs, c - cs) for r in range(rs, re) for c in range(cs, ce)
                   if grid[r][c] != 0]
            if pts:
                pattern = pts
                break
        if pattern:
            break

    out = [[0] * w for _ in range(h)]
    for r in sep_rows:
        out[r] = grid[r][:]
    for c in sep_cols:
        for r in range(h):
            out[r][c] = grid[r][c]

    for rs, re in zip(row_starts, row_ends):
        # The color associated with this band is in its first tile.
        color = next((grid[r][c] for r in range(rs, re)
                      for c in range(col_starts[0], col_ends[0])
                      if grid[r][c] != 0), 0)
        if not color or not pattern:
            continue
        for cs, ce in zip(col_starts, col_ends):
            for dr, dc in pattern:
                if rs + dr < re and cs + dc < ce:
                    out[rs + dr][cs + dc] = color
    return out
